import type { Register } from 'claude-code'

// 背景画像 (富士山と桜, 1792x1024 webp) を data URI で埋め込んだ SVG。
// Svg コンポーネントは画像ファイルを直接使えないため、SVG の <image> に包んで渡す。
const SCENE = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1792 1024" preserveAspectRatio="xMidYMid slice"><image width="1792" height="1024" preserveAspectRatio="xMidYMid slice" href="data:image/webp;base64,"/></svg>`

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const set = await $.theme.set({
      backdrop: { scene: 'night-sky', glass: { blur: 12, tint: '#0b1026', opacity: 0.45 } },
      overrideColorScheme: 'dark',
    })

    if (!set.isDrawn) {
      $.ui.status(set.reason)
    }

    return next(e)
  })

  on('ui.render', { component: 'Backdrop' }, ($, e, next) => {
    if (e.surface !== 'desktop' && e.surface !== 'mobile') {
      return next(e)
    }
    const { Svg } = $.ui.resolve(e)

    return <Svg source={SCENE} alt="Mt. Fuji and cherry blossoms" isInteractive />
  })
}
